package com.sagar.eventmanagement.cms;
import com.sagar.eventmanagement.entity.ServiceItem; import com.sagar.eventmanagement.repository.ServiceItemRepository; import org.springframework.boot.ApplicationArguments; import org.springframework.boot.ApplicationRunner; import org.springframework.stereotype.Component; import java.util.List;
@Component public class ServiceSeeder implements ApplicationRunner {
 private final ServiceItemRepository repo; public ServiceSeeder(ServiceItemRepository repo){this.repo=repo;}
 public void run(ApplicationArguments args){if(repo.count()>0)return;List<String[]> items=List.of(new String[]{"Wedding Planning","From the first date to the final farewell, we orchestrate every element of your celebration with precision, care, and creative vision.","assets/images/hero-baraat.jpeg"},new String[]{"Décor & Design","Lush floral installations, curated colour palettes, and immersive lighting — we design environments that move people.","assets/images/tailored-gallery-1.jpeg"},new String[]{"Vendor & Guest Management","Our curated vendor network brings you India's finest photographers, caterers, musicians, and artists.","assets/images/tailored-gallery-2.jpeg"},new String[]{"Complete Wedding Management","Our signature full-service package. We take full ownership of every function so you experience pure joy.","assets/images/tailored-gallery-3.jpeg"});int order=0;for(var item:items){var s=new ServiceItem();s.setName(item[0]);s.setDescription(item[1]);s.setImageUrl(item[2]);s.setPublished(true);s.setDisplayOrder(order++);repo.save(s);}}
}
